S: o resultado
public function checkout(Order $order): string
{
    if ($order-&gt;isEmpty()) {
        throw new DomainException('Pedido vazio');
    }
    $total = $this-&gt;discount-&gt;apply($order-&gt;subtotal());
    $receipt = $this-&gt;payment-&gt;pay($total);
    $this-&gt;repository-&gt;save($order, $total);
    $this-&gt;notifier-&gt;notify("Pedido pago: {$receipt}");

    return $receipt;
}

